//! Editor icon rendering and generated artwork.
pub(crate) mod generated;

// pn_icons -- PaintCraft's own colourful icons: vector layers (generated.rs, generated by
// tools/gen_pn_icons.py) drawn instead of the style's monochrome glyphs through the library's
// icon hook -- for the code points in the table and only in the normal text colours
// (disabled, accent or white icons stay glyphs).  The code points from PN_OWN_FIRST on are
// PaintCraft's own: the icon font has no glyph for them, so the hook draws them in every
// colour, in greys on a disabled row.  The style itself is not changed.
//                                                               [apps/PaintCraft/src/pn_icons.s]
//
//   pn_icons_init()      parse every layer's path once, install the hook
//   pn_icons_off()       (test hook) the library glyphs again
//   pn_icon_paint(cp, x, y, size_fx, text_argb, force_argb) -> drawn / unknown icon
//                        draw icon cp into the gfx target in any colours: layers without a
//                        colour get text_argb, force_argb != 0 paints every layer in it (a
//                        silhouette; the cursors draw their white halo with it)
//
// The hook runs at render time without the Ui: it compares the icon colour with the theme's
// T_TEXT / T_TEXT2 kept by pn_icons_colors (main.rs calls it at the start of every frame),
// which also keeps T_FLYOUT for the greys.

use alloc::rc::Rc;
use alloc::vec::Vec;
use core::cell::Cell;

use gfx::pathdata::PData;
use gfx::xform::Matrix;
use gfx::{CAP_ROUND, JOIN_ROUND, RULE_NONZERO};
use rt::fx::cvtd;
use ui::*;

use crate::workspace::icons::generated::{PN_ICON_TAB, PN_LAYER_TAB, PN_OWN_FIRST};
use crate::app::Pn;

/// the parsed layer paths (g_pi_pd)
pub(crate) struct IconSet {
    pd: Vec<PData>,
}

/// the state of pn_icons.s
pub(crate) struct PnIcons {
    pub(crate) set: Rc<IconSet>,
    /// the theme's T_TEXT / T_TEXT2 / T_FLYOUT for the render-time hook
    tc: Rc<Cell<[u32; 3]>>,
}

impl Default for PnIcons {
    fn default() -> PnIcons {
        PnIcons { set: Rc::new(IconSet { pd: Vec::new() }), tc: Rc::new(Cell::new([0; 3])) }
    }
}

/// pn_icons_init() -- the paths of every layer, then the hook
pub(crate) fn pn_icons_init(p: &mut Pn, ui: &mut Ui) {
    let mut pd = Vec::with_capacity(PN_LAYER_TAB.len());
    for l in PN_LAYER_TAB.iter() {
        let mut d = PData::new();
        d.parse(l.path.as_bytes());
        pd.push(d);
    }
    p.icons.set = Rc::new(IconSet { pd });
    pn_icons_colors(p, ui);
    let set = p.icons.set.clone();
    let tc = p.icons.tc.clone();
    let hook: IconHook = Rc::new(move |g: &mut Gfx, cp: u32, x: i32, y: i32, size: i32, argb: u32| -> bool {
        pn_icon_draw(&set, &tc, g, cp, x, y, size, argb)
    });
    ui.icon_hook(Some(hook));
}

/// the theme's text colours for the hook (start of every frame)
pub(crate) fn pn_icons_colors(p: &mut Pn, ui: &mut Ui) {
    p.icons.tc.set([ui.color(T_TEXT), ui.color(T_TEXT2), ui.color(T_FLYOUT)]);
}

/// pn_icons_off() -- the style's glyphs again
pub(crate) fn pn_icons_off(_p: &mut Pn, ui: &mut Ui) {
    ui.icon_hook(None);
}

// pn_icon_draw(cp, x, y, size_fx, argb) -> drawn -- (render time, the icon hook) the layers of
// icon cp scaled from the 16 grid into the size_fx box at x, y -- only for the normal text
// colours (disabled / on-accent icons stay glyphs, or grey layers where the font has none)
#[allow(clippy::too_many_arguments)]
fn pn_icon_draw(set: &IconSet, tc: &Cell<[u32; 3]>, g: &mut Gfx, cp: u32, x: i32, y: i32, size: i32, argb: u32) -> bool {
    let c = tc.get();
    if argb != c[0] && argb != c[1] {
        return cp >= PN_OWN_FIRST && icon_layers(set, g, cp, x, y, size, |l| icon_grey(l, argb, c[2]));
    }
    pn_icon_paint(set, g, cp, x, y, size, argb, 0)
}

// icon_grey(layer, argb, bg) -> the colour of a layer on a disabled row: from the row's colour on
// the flyout (dark parts of the art, text-coloured layers) towards the flyout (light parts), so
// the icon reads like a glyph in the disabled colour on both themes
fn icon_grey(layer: u32, argb: u32, bg: u32) -> u32 {
    let mix = |a: u32, b: u32, t: u32| -> u32 {
        (0..3).fold(0xFF00_0000, |o, k| {
            let (ca, cb) = ((a >> (k * 8)) & 255, (b >> (k * 8)) & 255);
            o | (((ca * (255 - t) + cb * t + 127) / 255) << (k * 8))
        })
    };
    let fg = mix(bg, argb, argb >> 24); // the row's colour may be translucent
    if layer == 0 {
        return fg;
    }
    let [b, g, r] = [layer & 255, (layer >> 8) & 255, (layer >> 16) & 255];
    let luma = (r * 54 + g * 183 + b * 19) >> 8;
    mix(fg, bg, luma * 3 / 4)
}

/// pn_icon_paint(cp, x, y, size_fx, text_argb, force_argb) -> drawn
#[allow(clippy::too_many_arguments)]
pub(crate) fn pn_icon_paint(set: &IconSet, g: &mut Gfx, cp: u32, x: i32, y: i32, size_fx: i32, text_argb: u32, force_argb: u32) -> bool {
    icon_layers(set, g, cp, x, y, size_fx, |l| {
        if force_argb != 0 {
            force_argb // a silhouette
        } else if l != 0 {
            l
        } else {
            text_argb // 0 = the text colour
        }
    })
}

// icon_layers(cp, x, y, size_fx, colour of a layer) -> drawn / unknown icon
fn icon_layers(set: &IconSet, g: &mut Gfx, cp: u32, x: i32, y: i32, size_fx: i32, colour: impl Fn(u32) -> u32) -> bool {
    let Some(ic) = PN_ICON_TAB.iter().find(|r| r.cp == cp) else { return false };
    let first = ic.first as usize;
    let end = (ic.first + ic.n) as usize;
    // matrix: scale = size / 16, translation = the box
    let s = size_fx as f64 * 0.000244140625; // (size_fx / 256) / 16
    let m = Matrix { a: s, b: 0.0, c: x as f64, d: 0.0, e: s, f: y as f64 };
    for k in first..end {
        let l = &PN_LAYER_TAB[k];
        g.dc.set_color(colour(l.argb));
        g.text.path.begin(g.dc);
        if let Some(pd) = set.pd.get(k) {
            pd.emit(&mut g.text.path, Some(&m));
        }
        if l.kind == 2 {
            // width (24.8 px) = width16 / 16 * scale * 256
            let w = cvtd(l.width as f64 * s * 16.0);
            g.text.path.stroke(&mut g.text.ras, g.dc, g.sf, w, JOIN_ROUND | (CAP_ROUND << 4));
        } else {
            g.text.path.fill(&mut g.text.ras, g.dc, g.sf, RULE_NONZERO);
        }
    }
    true
}
